#!/usr/bin/env python3
"""Compute ground truth for CSX-295_Q2 from local package files."""

from __future__ import annotations

import json
import math
import re
from collections.abc import Iterable, Iterator
from pathlib import Path

from PIL import Image


TASK_ID = "CSX-295_Q2"
EVENT_ID = "CSX-295"

SOURCE_FILES = [
    "metadata/event.json",
    "data/event_reports/event_reports_001_Locked_package_evidence_report.html",
    "data/event_reports/event_reports_003_Locked_event_anchor_Saharan_dust_storm_over_the_Atlantic_Ocean.json",
    "data/remote_sensing/remote_sensing_005_pre.jpg",
    "data/remote_sensing/remote_sensing_006_event.jpg",
    "data/physical_hazard/physical_hazard_005_GPM_IMERG_V07_event_accumulated_precipitation.json",
    "data/physical_hazard/physical_hazard_007_CHIRPS_daily_event_accumulated_precipitation.json",
]

PLUME_LENGTH_THRESHOLD_KM = 3000
NORTH_DELTA_THRESHOLD = 0.02
NS_CONTRAST_THRESHOLD = 0.08
CONTRAST_RATIO_THRESHOLD = 10.0
PRECIP_CELL_MAX_THRESHOLD_MM = 10.0


def repo_root() -> Path:
    return Path(__file__).resolve().parents[3]


def package_dir() -> Path:
    return repo_root() / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID


def read_json(package_root: Path, rel_path: str) -> dict:
    return json.loads((package_root / rel_path).read_text(encoding="utf-8-sig"))


def region_box(width: int, height: int, region: str) -> tuple[int, int, int, int]:
    if region == "full":
        return (0, 0, width, height)
    if region == "north":
        return (0, 0, width, height // 2)
    if region == "south":
        return (0, height // 2, width, height)
    raise ValueError(f"unsupported region: {region}")


def rgb_triplets(data: Iterable[object]) -> Iterator[tuple[float, float, float]]:
    pending: list[float] = []
    for item in data:
        if isinstance(item, (tuple, list)):
            if len(item) >= 3:
                yield float(item[0]), float(item[1]), float(item[2])
            continue
        try:
            value = float(item)
        except (TypeError, ValueError):
            continue
        pending.append(value)
        if len(pending) == 3:
            yield pending[0], pending[1], pending[2]
            pending.clear()


def image_rgb_stream(image: Image.Image) -> Iterator[tuple[float, float, float]]:
    flat_getter = getattr(image, "get_flattened_data", None)
    if callable(flat_getter):
        yield from rgb_triplets(flat_getter())
    else:
        yield from rgb_triplets(image.getdata())


def image_region_stats(image_path: Path, region: str) -> dict[str, float]:
    with Image.open(image_path) as source:
        image = source.convert("RGB")
    crop = image.crop(region_box(*image.size, region))
    dci_total = 0.0
    rb_total = 0.0
    kept = 0
    total = crop.size[0] * crop.size[1]

    for red, green, blue in image_rgb_stream(crop):
        brightness = (red + green + blue) / 3.0
        if brightness <= 20.0 or brightness >= 245.0:
            continue
        dci_total += (red + green) / (2.0 * max(blue, 1.0))
        rb_total += red - blue
        kept += 1

    if kept == 0:
        raise ValueError(f"no valid pixels in {image_path} {region}")

    return {
        "dci": round(dci_total / kept, 6),
        "red_minus_blue": round(rb_total / kept, 6),
        "valid_fraction": round(kept / total, 6),
    }


def image_comparison(package_root: Path) -> dict[str, dict[str, object]]:
    pre_path = package_root / "data/remote_sensing/remote_sensing_005_pre.jpg"
    event_path = package_root / "data/remote_sensing/remote_sensing_006_event.jpg"
    regions: dict[str, dict[str, object]] = {}
    for region in ("full", "north", "south"):
        pre = image_region_stats(pre_path, region)
        event = image_region_stats(event_path, region)
        regions[region] = {
            "pre": pre,
            "event": event,
            "delta_dci": round(event["dci"] - pre["dci"], 6),
            "delta_red_minus_blue": round(event["red_minus_blue"] - pre["red_minus_blue"], 6),
        }
    return regions


def extract_plume_length_km(html: str) -> int:
    plain = re.sub(r"<[^>]+>", " ", html)
    plain = re.sub(r"\s+", " ", plain)
    match = re.search(r"([0-9,]+)\s*km-long dust plume", plain, re.IGNORECASE)
    if not match:
        raise ValueError("reported plume length not found")
    return int(match.group(1).replace(",", ""))


def precipitation_values(package_root: Path) -> dict[str, object]:
    gpm = read_json(package_root, "data/physical_hazard/physical_hazard_005_GPM_IMERG_V07_event_accumulated_precipitation.json")
    chirps = read_json(package_root, "data/physical_hazard/physical_hazard_007_CHIRPS_daily_event_accumulated_precipitation.json")
    summaries = {
        "gpm": {
            "mean_mm": gpm["stats"]["gpm_event_precip_mm_mean"],
            "cell_max_mm": gpm["stats"]["gpm_event_precip_mm_max"],
        },
        "chirps": {
            "mean_mm": chirps["stats"]["chirps_event_precip_mm_mean"],
            "cell_max_mm": chirps["stats"]["chirps_event_precip_mm_max"],
        },
    }
    return {
        "summaries": summaries,
        "largest_mean_mm": round(max(item["mean_mm"] for item in summaries.values()), 6),
        "largest_cell_max_mm": round(max(item["cell_max_mm"] for item in summaries.values()), 6),
    }


def build_rubric() -> dict[str, object]:
    return {
        "total_points": 20,
        "criteria": [
            {
                "name": "Answer schema",
                "points": 3,
                "description": "Returns the requested compact JSON fields with numeric values and the conclusion label.",
                "partial_credit": "Award 1-2 points for mostly correct structure with missing fields or inconsistent rounding.",
            },
            {
                "name": "DCI formula",
                "points": 4,
                "description": "Applies the DCI formula and valid-pixel brightness filter correctly for full, northern, and southern regions.",
                "partial_credit": "Award 2 points for using the DCI formula but omitting or misapplying the brightness filter.",
            },
            {
                "name": "Regional image anchors",
                "points": 5,
                "description": "Computes north delta near 0.034708, south delta near -0.073720, full delta near -0.003583, and north-south contrast near 0.108428.",
                "partial_credit": "Award 1 point per correct image anchor, with 1 additional point for correct signs.",
            },
            {
                "name": "Threshold proof",
                "points": 5,
                "description": "Applies the threshold proof correctly, including the contrast-to-full ratio and pass state for the north-weighted image signal.",
                "partial_credit": "Award 2 points for the correct qualitative pass state with incomplete arithmetic.",
            },
            {
                "name": "Length and precipitation checks",
                "points": 2,
                "description": "Uses the reported plume length and largest event-total precipitation cell maximum in the consistency test.",
                "partial_credit": "Award 1 point for only one of these anchors.",
            },
            {
                "name": "Concise computed interpretation",
                "points": 1,
                "description": "Keeps the final computed consequence concise and does not assert measured aerosol concentration, surface damage, or realized impacts.",
                "partial_credit": "Award 1 point for a correct label with one minor overstatement.",
            },
        ],
    }


def main() -> None:
    package_root = package_dir()
    event_meta = read_json(package_root, "metadata/event.json")
    anchor = read_json(package_root, "data/event_reports/event_reports_003_Locked_event_anchor_Saharan_dust_storm_over_the_Atlantic_Ocean.json")
    html = (package_root / "data/event_reports/event_reports_001_Locked_package_evidence_report.html").read_text(encoding="utf-8-sig")

    regions = image_comparison(package_root)
    plume_length_km = extract_plume_length_km(html)
    precip = precipitation_values(package_root)

    north_delta = regions["north"]["delta_dci"]
    south_delta = regions["south"]["delta_dci"]
    full_delta = regions["full"]["delta_dci"]
    ns_contrast = round(north_delta - south_delta, 6)
    contrast_ratio = round(ns_contrast / max(abs(full_delta), 0.001), 3)
    precip_cell_max = precip["largest_cell_max_mm"]

    image_pass = (
        north_delta >= NORTH_DELTA_THRESHOLD
        and south_delta < 0
        and ns_contrast >= NS_CONTRAST_THRESHOLD
        and contrast_ratio >= CONTRAST_RATIO_THRESHOLD
    )
    plume_pass = plume_length_km >= PLUME_LENGTH_THRESHOLD_KM
    low_rain_pass = precip_cell_max < PRECIP_CELL_MAX_THRESHOLD_MM
    conclusion = "north_weighted_transported_dust_consistent" if image_pass and plume_pass and low_rain_pass else "not_consistent"

    canonical_answer = {
        "plume_length_km": plume_length_km,
        "north_delta_dci": north_delta,
        "south_delta_dci": south_delta,
        "full_delta_dci": full_delta,
        "ns_contrast_dci": ns_contrast,
        "contrast_to_abs_full": contrast_ratio,
        "precip_largest_cell_max_mm": precip_cell_max,
        "conclusion": conclusion,
    }

    result = {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "short_answer",
        "evaluation_mode": "deterministic",
        "difficulty_level": "L3",
        "target_family": "saharan_dust_dci_transport_consistency_proof",
        "primary_gt": {
            "canonical_answer": canonical_answer,
            "diagnosis_label": conclusion,
            "required_metrics": ["plume_length_km", "dci_delta_by_region", "ns_contrast_dci", "contrast_to_abs_full", "precip_largest_cell_max_mm"],
            "rules": {
                "image_pass": "north_delta_dci>=0.02 and south_delta_dci<0 and ns_contrast_dci>=0.08 and contrast_to_abs_full>=10",
                "plume_pass": "plume_length_km>=3000",
                "low_rain_pass": "precip_largest_cell_max_mm<10",
            },
            "tolerances": {"dci": 0.0005, "ratio": 0.2, "precip_mm": 0.01, "plume_km": 1},
        },
        "key_values": {
            "event_name": event_meta["event_name"],
            "hazard_family": event_meta["hazard_family"],
            "event_window": {
                "start": anchor["temporal_window"]["start_date"],
                "end": anchor["temporal_window"]["end_date"],
            },
            "formulas": {
                "dci": "mean((R+G)/(2*max(B,1))) over valid pixels with 20<brightness<245",
                "delta_dci": "event_dci-pre_dci",
                "ns_contrast_dci": "north_delta_dci-south_delta_dci",
                "contrast_to_abs_full": "ns_contrast_dci/max(abs(full_delta_dci),0.001)",
            },
            "thresholds": {
                "plume_length_km_min": PLUME_LENGTH_THRESHOLD_KM,
                "north_delta_dci_min": NORTH_DELTA_THRESHOLD,
                "ns_contrast_dci_min": NS_CONTRAST_THRESHOLD,
                "contrast_to_abs_full_min": CONTRAST_RATIO_THRESHOLD,
                "precip_cell_max_mm_wet_cutoff": PRECIP_CELL_MAX_THRESHOLD_MM,
            },
            "image_regions": regions,
            "precipitation": precip,
            "checks": {
                "image_pass": image_pass,
                "plume_pass": plume_pass,
                "low_rain_pass": low_rain_pass,
                "uniform_scene_increase": north_delta > 0 and south_delta > 0 and full_delta > 0,
            },
        },
        "rubric": build_rubric(),
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": SOURCE_FILES,
            "notes": "All values are computed from local CSX-295 package files; no network access is used.",
        },
    }

    output = Path(__file__).resolve().parent / "computed_gt.json"
    output.write_text(json.dumps(result, indent=2, ensure_ascii=True) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
